-- Stage 10A.1: narrow FIELD_OFFICER administrative feeder/threshold scope.
CREATE OR REPLACE FUNCTION public.get_my_manageable_feeder_station_ids() RETURNS TABLE(station_id uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_role public.app_user_role; BEGIN SELECT role INTO v_role FROM public.app_users WHERE id=auth.uid() AND active; IF v_role IN ('ADMIN'::public.app_user_role,'SUPER_ADMIN'::public.app_user_role) THEN RETURN QUERY SELECT id FROM public.stations WHERE active; RETURN; END IF; IF v_role='FIELD_OFFICER'::public.app_user_role THEN RETURN QUERY SELECT DISTINCT station_id FROM (SELECT us.station_id FROM public.user_stations us JOIN public.stations s ON s.id=us.station_id WHERE us.user_id=auth.uid() AND us.active AND s.active UNION SELECT sou.station_id FROM public.station_org_units sou JOIN public.stations s ON s.id=sou.station_id JOIN public.get_my_accessible_org_unit_ids() ao ON ao.org_unit_id=sou.org_unit_id WHERE sou.active AND s.active) scoped; END IF; END; $$;
CREATE OR REPLACE FUNCTION public.audit_scope_allowed(p_station uuid,p_office uuid,p_visibility text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE public.get_my_role() WHEN 'SUPER_ADMIN'::public.app_user_role THEN true WHEN 'ADMIN'::public.app_user_role THEN p_visibility IN ('SCOPED','ADMIN_GLOBAL') WHEN 'FIELD_OFFICER'::public.app_user_role THEN p_visibility='SCOPED' AND ((p_station IS NOT NULL AND EXISTS(SELECT 1 FROM public.get_my_manageable_feeder_station_ids() s WHERE s.station_id=p_station)) OR (p_office IS NOT NULL AND EXISTS(SELECT 1 FROM public.get_my_accessible_org_unit_ids() o WHERE o.org_unit_id=p_office))) ELSE false END; $$;
GRANT EXECUTE ON FUNCTION public.get_my_manageable_feeder_station_ids() TO authenticated;
